#!/usr/bin/env bash
set -Eeuo pipefail

say(){ printf '\n\033[1;36m%s\033[0m\n' "$*"; }
fail(){ printf '\n\033[1;31mERROR: %s\033[0m\n' "$*" >&2; exit 1; }

[[ -f package.json ]] || fail "เปิด Terminal ที่ระดับเดียวกับ package.json ก่อน"
[[ -d .git ]] || fail "โฟลเดอร์นี้ไม่ใช่ Git repository"

CURRENT_VERSION=$(node -p "require('./package.json').version" 2>/dev/null || true)
[[ "$CURRENT_VERSION" == "9.5.0" || "$CURRENT_VERSION" == "9.6.0" ]] || fail "ต้องอัปเดตจาก v9.5.0 (พบ $CURRENT_VERSION)"

# Allow only this installer as an uncommitted file.
DIRTY=$(git status --porcelain | grep -vE '^\?\? v96\.sh$|^ M v96\.sh$|^A  v96\.sh$' || true)
[[ -z "$DIRTY" ]] || fail "มีไฟล์อื่นยังไม่ Commit กรุณา Commit หรือยกเลิกก่อน:\n$DIRTY"

STAMP=$(date +%Y%m%d-%H%M%S)
BACKUP=".git/GOLD-PULSE-v9.5-backup-$STAMP.tar.gz"
PATCH_FILE="$(mktemp)"
cleanup(){ rm -f "$PATCH_FILE"; }
trap cleanup EXIT

say "1/5 สำรองไฟล์เดิมไว้ที่ $BACKUP"
tar -czf "$BACKUP" \
  .env.example CHANGELOG.md FILELIST.txt README.md \
  app/api/gold/route.js app/api/health/route.js app/api/scan/route.js \
  app/layout.js app/page.js lib/alerts.ts lib/config.ts package.json \
  public/manifest.webmanifest public/sw.js

say "2/5 ติดตั้ง GOLD PULSE X v9.6 ACTIVE SIGNAL"
base64 -d > "$PATCH_FILE" <<'PATCH_BASE64'

PATCH_BASE64
tar -xzf "$PATCH_FILE" -C .

say "3/5 ตรวจสอบ Syntax และโครงสร้าง"
find app lib scripts -type f \( -name '*.js' -o -name '*.mjs' \) -print0 | xargs -0 -n1 node --check
node scripts/static-check.mjs
node -e "const p=require('./package.json'); if(p.version!=='9.6.0') process.exit(1); console.log('✅ Version',p.version)"

say "4/5 Commit การอัปเดต"
rm -f v96.sh
git add -A
if git diff --cached --quiet; then
  say "ไม่มีไฟล์ใหม่ให้ Commit — v9.6 ถูกติดตั้งอยู่แล้ว"
else
  git commit -m "Upgrade GOLD PULSE X to v9.6 Active Signal"
fi

say "5/5 Push ไป GitHub"
git push origin HEAD:main

printf '\n\033[1;32mSUCCESS: v9.6 Active Signal pushed to GitHub.\033[0m\n'
printf 'Vercel จะ Deploy อัตโนมัติ\n'
printf 'Active profile: Probability 60 / Score 54 / Cooldown 20 นาที / อย่างน้อย 2 confirmations\n'
printf 'เป้าหมายประมาณ 20 alerts ต่อวัน ไม่รับประกันจำนวนหรือผลกำไร\n'
